@page "/modes"
@rendermode InteractiveServer

<p>Mode: @RendererInfo.Name / Interactive: @RendererInfo.IsInteractive</p>
<p>Clicks: @count</p>
<p>Last click: @(lastClick?.ToString("HH:mm:ss") ?? "never")</p>
<button @onclick="Click">Click me</button>

@code {
    private int count;
    private DateTime? lastClick;

    private void Click()
    {
        count++;
        lastClick = DateTime.Now;
    }
}
